source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    n = len(grid)
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 2:
                continue
            orbit = {(r, c), (n - 1 - r, c), (r, n - 1 - c), (n - 1 - r, n - 1 - c),
                     (c, r), (n - 1 - c, r), (c, n - 1 - r), (n - 1 - c, n - 1 - r)}
            known = [grid[y][x] for y, x in orbit if grid[y][x] != 2]
            if known:
                out[r][c] = Counter(known).most_common(1)[0][0]
    return out
'''
